namespace BookInventory.Application.Iam.Companies;

/// <summary>
/// The capability the <c>company</c> module calls to create a company's Owner login (R61). <c>iam</c> owns the account,
/// the uniqueness of the user id, e-mail and mobile (R1) and the temporary password (R57); the user id is generated by
/// the caller from the company's name.
/// <para>
/// It runs inside the caller's request transaction and throws the usual business exceptions (409 duplicate, 400
/// invalid), which roll that transaction back, so a company is never saved without its Owner.
/// </para>
/// </summary>
public interface IOwnerAccountCreation
{
    Task<OwnerAccountCreated> CreateAsync(OwnerRegistration registration, CancellationToken cancellationToken = default);
}
